     if (recursive) {
       return (WINDOWS) ?
-          new String[] { getWinutilsPath(), "chmod", "-R", perm }
+          new String[] { getWinUtilsPath(), "chmod", "-R", perm }
           : new String[] { "chmod", "-R", perm };
     } else {
